  'repeat.toast_saved': "Gemt. Udgiv for at sende det ud på skærmene.",
  'widget.web.interactive': "Interaktiv (selvbetjeningskiosk)",
  'widget.web.interactive_hint': "Besøgende kan trykke, scrolle og udfylde formularer. Playlisten holder pause, mens nogen bruger siden, og når de går, nulstilles siden, og alt, hvad de har gjort, slettes. Kun fuld skærm. Fuld understøttelse på Android, de native Windows- og Raspberry Pi-afspillere og BrightSign; web-, webOS- og Tizen-skærme får en begrænset version, der ikke kan slette sidens data eller blokere andre sider.",
  'widget.web.idle_timeout': "Nulstil efter så mange sekunder uden berøring",
  'widget.web.allowed_domains': "Andre sider, besøgende må åbne",
  'widget.web.allowed_domains_ph': "f.eks. checkout.example.com, maps.example.com",
  'widget.web.allowed_domains_hint': "Sidens eget websted er altid tilladt. Links til alle andre steder blokeres.",
  'widget.web.home_button': "Vis en Hjem-knap, når en besøgende forlader startsiden",
  'widget.web.idle_warning': "Nedtælling med \"Er du der stadig?\" før nulstilling",
  'widget.web.idle_warning_off': "Fra (nulstil med det samme)",
  'widget.web.idle_warning_sec': "{n} sekunder",
  'widget.web.idle_warning_hint': "Giver en besøgende et øjeblik til at trykke og fortsætte. Nyttigt i en butik; på en informationsside kan det være slået fra.",
  'widget.web.wipe_site_data': "Slet webstedets cookies og lagring efter hver besøgende",
  'widget.web.wipe_site_data_hint': "Slå fra for informationssider uden noget at beskytte (menuer, prislister, kort): så bliver cookiebanneret og det valgte sprog. Hver besøgende får stadig en frisk side, historik og formulardata. Lagringen deles af alle websider på en skærm, så hvis et andet element sletter på samme skærm, ryddes den også. Windows- og Raspberry Pi-afspillerne beholder cookies, men ikke webstedslagring; BrightSign sletter altid.",
  'widget.web.keep_consent': "Behold webstedets cookiesamtykke mellem besøgende",
  'widget.web.keep_consent_hint': "Kun samtykkecookies fra de tilladte websteder beholdes. Logins, kurve og alt andet slettes stadig efter hver besøgende. Samtykkeværktøjer, der gemmer valget i localStorage i stedet for i en cookie, vil stadig spørge.",
  'widget.web.keep_cookie_names': "Andre cookienavne, der skal beholdes",
  'widget.web.keep_cookie_names_ph': "f.eks. shop_consent, cc_*",
  'widget.web.keep_cookie_names_hint': "Almindelige samtykkeværktøjer (Cookiebot, OneTrust, IAB TCF, CookieYes, Complianz, Borlabs, iubenda, Didomi m.fl.) genkendes allerede. En * til sidst matcher et præfiks. Tilføj aldrig en login- eller kurvcookie her.",
  'widget.web.zoom_hint': "Zoom % ovenfor gælder også for den interaktive side: 150 får et desktopwebsted til at blive vist, som om skærmen var to tredjedele så stor.",
  'device.event.web_error': "Websiden fejlede",
