  'device.caps.web_interactive_full': "fuld (webstedet åbner i sin egen browser; links uden for de tilladte websteder blokeres, og alt slettes efter hver besøgende)",
  'device.caps.web_interactive_framed': "begrænset (webstedet kører i en ramme: websteder, der afviser rammer, forbliver tomme, og skærmen kan ikke blokere andre websteder eller slette det, en besøgende efterlader, så et login kan overleve nulstillingen)",
