  'nav.platform.rollouts': "Udrulning af afspillere",
  'platform.tab.rollouts': "Udrulning af afspillere",
  'platform.rollouts.title': "Udrulning af afspillere",
  'platform.rollouts.subtitle': "Nye afspillerversioner når skærmene i bølger og stopper af sig selv, hvis de klarer sig dårligere",
  'platform.rollouts.desc': "En ny Android-, Pi- eller Windows-afspiller sendes først til 10 % af platformens skærme, så 50 % og derefter alle, og hver bølge venter, til de opdaterede skærme ser sunde ud. Hvis opdaterede skærme går ned eller går i sort oftere end resten, stopper udrulningen af sig selv, og du får en e-mail. Pi- og Windows-skærme, der fik en stoppet version, sendes tilbage til den forrige. Android kan ikke gå tilbage til en ældre version, så dér stopper et stop spredningen, og løsningen er en nyere build. Skærme på betakanalen og en Gennemtving opdatering springer bølgerne over.",
  'platform.rollouts.disabled': "Bølger er slået fra på denne server (OTA_STAGED_ROLLOUT=off): alle skærme får tilbudt en ny version på én gang.",
