  'auto.signing': "Signering af forespørgsler (valgfrit)",
  'auto.signing_hint': "Hvis afsenderen signerer sine forespørgsler med en delt hemmelighed (HMAC-SHA256), så indtast den her, og usignerede forespørgsler afvises.",
  'auto.signing_set': "Der er angivet en hemmelighed — lad feltet være tomt for at beholde den",
  'auto.signing_none': "Ingen hemmelighed angivet",
  'auto.signing_remove': "Fjern signeringshemmeligheden",
  'simple.help.g1.title': "Forbind en skærm",
  'simple.help.g1.s1': "Åbn afspilleren på det TV, den tablet eller computer, du vil bruge: installér Android-appen, eller åbn denne sides /player-side i enhedens webbrowser.",
  'simple.help.g1.s2': "Har du ikke et TV ved hånden? Åbn afspilleren i en anden browserfane for at prøve.",
  'simple.help.g1.s3': "Afspilleren viser en 6-cifret kode. Vælg \"Tilføj en skærm\" her, og indtast den.",
  'simple.help.g1.s4': "Giv skærmen et navn, du kan genkende, f.eks. \"Forvindue\".",
  'simple.help.g2.title': "Skift, hvad en skærm viser",
  'simple.help.g2.s1': "Vælg \"Skift, hvad en skærm viser\", eller tryk på skærmen under \"Dine skærme\".",
  'simple.help.g2.s2': "Vælg \"Erstat\" for kun at vise det nye, eller \"Tilføj\" for at beholde det, der allerede afspilles.",
  'simple.help.g2.s3': "Upload fotos eller videoer, vælg nogle, du har uploadet før, eller vis det samme som en anden skærm.",
  'simple.help.g2.s4': "Skærmen opdateres inden for få sekunder.",
  'simple.help.g3.title': "Upload fotos og videoer",
  'simple.help.g3.s1': "Vælg \"Upload fotos\", og vælg så mange filer, du vil, eller træk dem ind.",
  'simple.help.g3.s2': "Sæt flueben ved de skærme, der skal vise dem, eller fjern alle flueben for at gemme dem til senere.",
  'simple.help.g3.s3': "Fotos vises i 10 sekunder hver; videoer afspilles til ende.",
  'simple.help.q1': "Hvad kan jeg bruge som skærm?",
  'simple.help.a1': "Android-TV'er, TV-bokse og tablets, Fire TV, smart-TV'er fra LG og Samsung, Raspberry Pi, Windows og ChromeOS — eller enhver enhed med en webbrowser.",
  'simple.help.q2': "Min skærm skifter ikke. Hvad skal jeg tjekke?",
  'simple.help.a2': "Sørg for, at skærmen står som \"Afspiller\" på forsiden. Hvis der står \"Offline\", så tjek, at enheden er tændt og forbundet til internettet; den henter dine ændringer, så snart den får forbindelse igen.",
  'simple.help.q3': "Hvad sker der, hvis internettet går ned?",
  'simple.help.a3': "Skærmene gemmer indholdet lokalt og bliver ved med at afspille det. Nye ændringer kommer, når forbindelsen er tilbage.",
  'simple.help.q4': "Hvilke filer kan jeg uploade?",
  'simple.help.a4': "Fotos (JPEG, PNG, GIF, WebP) og videoer (MP4 virker bedst) samt lyd. PDF'er kan uploades fra siden Indhold i Avanceret visning.",
  'simple.help.q5': "Hvordan omdøber eller fjerner jeg en skærm?",
  'simple.help.a5': "Skift til Avanceret (øverst til højre), åbn Skærme, klik på skærmen, og brug så Omdøb eller Fjern øverst på dens side.",
  'simple.help.q6': "Kan jeg vise forskellige ting på forskellige tidspunkter af dagen?",
  'simple.help.a6': "Ja — det hedder Tidsplan og findes i Avanceret visning. Enkel visning viser altid det samme indhold på en skærm, indtil du ændrer det.",
  'simple.help.trial_q': "Hvordan fungerer den gratis prøveperiode?",
  'simple.help.trial_a': "Du får 14 dage med Pro-planen, hvor alle funktioner er låst op, og der kræves intet kort. Når den slutter, overgår du til Free-planen: intet slettes, og skærme ud over Free-planens grænse sættes på pause, indtil du vælger en plan.",
  'stats.prompt.title': "Vil du hjælpe med at vise, hvor udbredt ScreenTinker er?",
  'stats.prompt.body': "Fordi de fleste installationer er private, kan vi ikke se, hvor mange skærme der findes derude. Deling sender et tilfældigt ID, versionen og hvor mange skærme du kører — aldrig andet. Du kan ændre det når som helst i Indstillinger.",
  'stats.prompt.share': "Del",
  'stats.prompt.no': "Nej tak",
  'stats.prompt.thanks': "Tak — installationsstatistik deles",
