  'migrate.self_hosted_note': "Din server skal kunne nås fra denne ScreenTinker-server. Adresser på et privat netværk blokeres, medmindre en administrator tillader dem.",
  'migrate.key_note': "Nøglen bruges kun til denne import. Den opbevares krypteret i højst et par timer og slettes, når importen slutter. Læseadgang er nok.",
