  'migrate.field.timezone': "Tidszone",
  'migrate.field.region': "Region",
  'migrate.how.xibo': "I Xibo skal du åbne Administration og derefter Applications og tilføje en Application med \"Client Credentials\" afkrydset. Kopiér dens Client ID og Client Secret. Indtast din CMS-adresse (den, du logger ind på), f.eks. https://cms.example.com.",
  'migrate.how.yodeck': "I Yodeck skal du åbne Account Settings, Advanced Settings, API Tokens og generere et token (Premium- eller Enterprise-plan). Indsæt det som label:token. Yodeck udleverer ikke originale uploadede billeder og dokumenter via sit API: de vises på en liste, så du kan tilføje dem med zip-importen. Videoer kommer over i den version, Yodeck afspiller.",
  'migrate.how.optisigns': "OptiSigns har et API, men det dokumenterer ingen måde at downloade dine filer på, så en playliste ville komme tom over. Download dine filer fra OptiSigns, og brug zip-importen: én mappe pr. playliste eller en playlists.csv.",
  'migrate.how.screencloud': "I ScreenCloud Studio skal du åbne Account Settings og derefter fanen Developer og oprette et token med læserettigheder. Vælg den region, der vises der (EU eller US). ScreenCloud gemmer tidsregler på de enkelte kanalelementer; de vises på en liste, men importeres ikke.",
  'migrate.how.anthias': "Indtast adressen på din Anthias-enhed, f.eks. http://192.168.1.20. Hvis du har slået godkendelse til, så indtast brugernavn og adgangskode. Hver enhed importeres som én skærm med én playliste.",
  'migrate.how.screenly': "I Screenly skal du åbne Settings, Security, Tokens og tilføje et token. Playlister, labels og skærme kommer over; simple dag- og tidsregler bliver til tidsplaner.",
  'migrate.how.generic_zip': "Upload en zip med dine medier. Hver mappe bliver til en playliste. Tilføj eventuelt playlists.csv (kolonner: playlist, file, duration, order) og screens.csv (kolonner: name, group, playlist).",
